using PrintDeck.Domain.Files;
using PrintDeck.Domain.Files.Enums;
using PrintDeck.Domain.Settings;

namespace PrintDeck.Domain.Tests.Files;

public class GcodeProblemCheckTests
{
	private static readonly PrinterProfile _mk3s = new() { Name = "MK3S", BedWidth = 250, BedDepth = 210, MaxHeight = 210 };

	private const string Clean = """
		; generated by PrusaSlicer 2.8.1
		M104 S215
		M140 S60
		M109 S215
		G28
		G90
		M83
		G1 Z0.2 F720
		G1 Y-3 F1000
		G1 X60 E9 F1000 ; purge line just off the bed
		G1 X100 E12.5
		G92 E0
		G1 X120 Y100 F6000
		G1 X130 Y100 E0.5 F1500
		M104 S0
		""";

	private static IReadOnlyList<GcodeProblem> Check(string gcode, PrinterProfile? profile = null)
	{
		GcodeProblemCheck check = new(profile ?? _mk3s);
		foreach (string line in gcode.Split('\n')) check.Inspect(line.TrimEnd('\r'));
		return check.Finish();
	}

	private static GcodeProblem Only(IReadOnlyList<GcodeProblem> problems, GcodeProblemKind kind) => Assert.Single(problems, p => p.Kind == kind);

	[Fact]
	public void A_normal_file_with_a_purge_line_has_no_problems() => Assert.Empty(Check(Clean));

	[Fact]
	public void Binary_gcode_is_an_error_and_stops_the_check()
	{
		IReadOnlyList<GcodeProblem> problems = Check("GCDE\u0001\0\0garbage\nM112\n");
		GcodeProblem binary = Assert.Single(problems);
		Assert.Equal((GcodeProblemKind.BinaryFile, GcodeProblemSeverity.Error), (binary.Kind, binary.Severity));
	}

	[Theory]
	[InlineData("M104 S{material_print_temperature}", "{material_print_temperature}")]
	[InlineData("M140 S[first_layer_bed_temperature]", "[first_layer_bed_temperature]")]
	[InlineData("M190 S{ first_layer_bed_temperature[0] }", "{ first_layer_bed_temperature[0] }")]
	public void Unfilled_placeholders_are_errors(string line, string placeholder)
	{
		GcodeProblem p = Only(Check(Clean + "\n" + line), GcodeProblemKind.UnreplacedPlaceholder);
		Assert.Equal(GcodeProblemSeverity.Error, p.Severity);
		Assert.Contains(placeholder, p.Message);
		Assert.Equal(16, p.FirstLine);
	}

	[Fact]
	public void Placeholders_in_comments_are_fine() => Assert.Empty(Check(Clean + "\n; start gcode for {printer_model}"));

	[Theory]
	[InlineData("M112")]
	[InlineData("M110 N0")]
	[InlineData("M28 PART.GCO")]
	[InlineData("M29")]
	[InlineData("M997")]
	public void Commands_that_break_a_streamed_print_are_errors(string line)
	{
		GcodeProblem p = Only(Check(Clean + "\n" + line), GcodeProblemKind.BreaksStreaming);
		Assert.Equal(GcodeProblemSeverity.Error, p.Severity);
	}

	[Fact]
	public void Repeats_are_counted_from_the_first_line()
	{
		GcodeProblem p = Only(Check(Clean + "\nM112\nG1 X1\nM112"), GcodeProblemKind.BreaksStreaming);
		Assert.Equal((16L, 2), (p.FirstLine!.Value, p.Count));
	}

	[Fact]
	public void Long_lines_are_a_warning()
	{
		GcodeProblem p = Only(Check(Clean + "\nM117 " + new string('x', 80)), GcodeProblemKind.LineTooLong);
		Assert.Equal(GcodeProblemSeverity.Warning, p.Severity);
	}

	[Fact]
	public void Long_comments_are_fine() => Assert.Empty(Check(Clean + "\nG1 X1 ; " + new string('x', 200)));

	[Fact]
	public void Extrusion_outside_the_profile_is_a_warning()
	{
		IReadOnlyList<GcodeProblem> problems = Check(Clean + "\nG1 X300 Y100 E2");

		GcodeProblem p = Only(problems, GcodeProblemKind.OutsideBuildVolume);
		Assert.Equal(GcodeProblemSeverity.Warning, p.Severity);
		Assert.Contains("X 0–300, Y -3–100, Z up to 0.2 mm", p.Message);
		Assert.Contains("MK3S is 250 × 210 × 210 mm", p.Message);
		Assert.Equal(16, p.FirstLine);
	}

	[Fact]
	public void Travel_outside_the_bed_and_relative_moves_inside_it_are_fine()
	{
		Assert.Empty(Check(Clean + "\nG1 X300 Y100 F6000"));
		Assert.Empty(Check(Clean + "\nG91\nG1 X50 E1\nG1 X50 E1\nG90"));
	}

	[Fact]
	public void Relative_moves_that_end_outside_are_caught()
	{
		Only(Check(Clean + "\nG91\nG1 X100 E1\nG1 X100 E1"), GcodeProblemKind.OutsideBuildVolume);
	}

	[Fact]
	public void Too_tall_is_outside_too() =>
		Assert.Contains("Z up to 250 mm", Only(Check(Clean + "\nG1 Z250\nG1 X121 E0.1"), GcodeProblemKind.OutsideBuildVolume).Message);

	[Fact]
	public void Flat_files_leave_z_out_of_the_message() =>
		Assert.DoesNotContain("Z up to", Only(Check("M109 S210\nG28\nG1 X10 Y10\nG1 X330 Y10 E5"), GcodeProblemKind.OutsideBuildVolume).Message);

	[Fact]
	public void Extruding_before_any_hotend_temperature_is_a_warning()
	{
		GcodeProblem p = Only(Check("G28\nG1 X10 Y10 E1"), GcodeProblemKind.NoHotendTemperature);
		Assert.Equal((GcodeProblemSeverity.Warning, 2L), (p.Severity, p.FirstLine!.Value));
		Assert.Empty(Check("M104 R200\nG28\nG1 X10 Y10 E1"));
	}

	[Fact]
	public void A_file_that_never_moves_is_a_warning() =>
		Assert.Equal(GcodeProblemKind.NoMoves, Assert.Single(Check("; nothing\nM104 S0")).Kind);

	[Fact]
	public void Errors_come_first()
	{
		IReadOnlyList<GcodeProblem> problems = Check("G28\nG1 X10 Y10 E1\nM112");
		Assert.Equal([GcodeProblemKind.BreaksStreaming, GcodeProblemKind.NoHotendTemperature], problems.Select(p => p.Kind));
	}
}
